 1| /**
 2|  * loyalty-discount: thanks long-standing customers.
 3|  *
 4|  * The rule: a customer who has bought from us for five years or more gets 2%
 5|  * off the subtotal, rounded to the cent.
 6|  * Example: 7 years, subtotal 500.00 → `loyaltyDiscount = 10`.
 7|  */
 8| import { roundCents } from '../../money.mjs';
 9| 
10| export const purpose = 'Give long-standing customers their loyalty discount.';
11| 
12| /** Years of buying from which the loyalty discount applies. */
13| const LOYAL_YEARS = 5;
14| /** The loyalty discount, as a share of the subtotal. */
15| const LOYAL_RATE = 0.02;
16| 
17| /** @param {any} scope */
18| export function run(scope) {
19|   const years = scope.customer.memberYears;
20|   scope.loyaltyDiscount = years >= LOYAL_YEARS ? roundCents(scope.subtotal * LOYAL_RATE) : 0;
21| }
